package com.moodtools.hub

internal object LauncherTranslationChunk0 {
    val entries = mapOf(
        "A launcher update is available" to arrayOf("May available na update para sa launcher", "\uB7F0\uCC98 \uC5C5\uB370\uC774\uD2B8\uAC00 \uAC00\uB2A5\uD569\uB2C8\uB2E4", "\u30E9\u30F3\u30C1\u30E3\u30FC\u306E\u66F4\u65B0\u304C\u5229\u7528\u53EF\u80FD\u3067\u3059", "\u542F\u52A8\u5668\u66F4\u65B0\u53EF\u7528", "Hay una actualizaci\u00F3n del lanzador disponible", "C\u1EADp nh\u1EADt tr\u00ECnh kh\u1EDFi ch\u1EA1y c\u00F3 s\u1EB5n", "Pembaruan peluncur tersedia", "Uma atualiza\u00E7\u00E3o do launcher est\u00E1 dispon\u00EDvel", "يتوفر تحديث قاذفة"),
        "A polished update experience, ready for the next signed launcher release." to arrayOf("Mas pinakintab na karanasan sa pag-update, handa para sa susunod na bersyon ng signed launcher.", "\uB2E4\uB4EC\uC5B4\uC9C4 \uC5C5\uB370\uC774\uD2B8 \uACBD\uD5D8, \uB2E4\uC74C \uC11C\uBA85\uB41C \uB7F0\uCC98 \uB9B4\uB9AC\uC2A4\uB97C \uB300\uBE44.", "\u6D17\u7DF4\u3055\u308C\u305F\u66F4\u65B0\u4F53\u9A13\u3002\u6B21\u56DE\u7F72\u540D\u3055\u308C\u305F\u30E9\u30F3\u30C1\u30E3\u30FC\u30EA\u30EA\u30FC\u30B9\u306B\u5BFE\u5FDC\u6E08\u307F\u3002", "\u7CBE\u5FC3\u4F18\u5316\u7684\u66F4\u65B0\u4F53\u9A8C\uFF0C\u5DF2\u51C6\u5907\u597D\u4E0B\u4E00\u4E2A\u7B7E\u540D\u542F\u52A8\u5668\u7248\u672C\u3002", "Una experiencia de actualizaci\u00F3n pulida, lista para la pr\u00F3xima versi\u00F3n firmada del lanzador.", "Tr\u1EA3i nghi\u1EC7m c\u1EADp nh\u1EADt \u0111\u01B0\u1EE3c ho\u00E0n thi\u1EC7n, s\u1EB5n s\u00E0ng cho phi\u00EAn b\u1EA3n tr\u00ECnh kh\u1EDFi ch\u1EA1y \u0111\u00E3 k\u00FD ti\u1EBFp theo.", "Pengalaman pembaruan yang sempurna, siap untuk rilisan peluncur yang ditandatangani berikutnya.", "Uma experi\u00EAncia de atualiza\u00E7\u00E3o aprimorada, pronta para a pr\u00F3xima vers\u00E3o assinada do launcher.", "تجربة تحديث مصقولة، جاهزة لإصدار المشغل الموقع التالي."),
        "Access check did not complete" to arrayOf("Hindi nakumpleto ang tseke sa access", "\uC811\uADFC \uD655\uC778\uC774 \uC644\uB8CC\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4", "\u30A2\u30AF\u30BB\u30B9\u78BA\u8A8D\u304C\u5B8C\u4E86\u3057\u307E\u305B\u3093\u3067\u3057\u305F", "\u8BBF\u95EE\u68C0\u67E5\u672A\u5B8C\u6210", "La verificaci\u00F3n de acceso no se complet\u00F3", "Ki\u1EC3m tra quy\u1EC1n truy c\u1EADp ch\u01B0a ho\u00E0n t\u1EA5t", "Pemeriksaan akses tidak selesai", "A verifica\u00E7\u00E3o de acesso n\u00E3o foi conclu\u00EDda", "لم يكتمل التحقق من الوصول"),
        "Account identity" to arrayOf("Pagkakakilanlan ng account", "\uACC4\uC815 \uC2E0\uC6D0", "\u30A2\u30AB\u30A6\u30F3\u30C8\u306E\u8B58\u5225", "\u8D26\u6237\u8EAB\u4EFD", "Identidad de la cuenta", "Nh\u1EADn d\u1EA1ng t\u00E0i kho\u1EA3n", "Identitas akun", "Identidade da conta", "هوية الحساب"),
        "Account identity is unavailable on this device." to arrayOf("Hindi available ang pagkakakilanlan ng account sa device na ito.", "\uC774 \uC7A5\uCE58\uC5D0\uC11C \uACC4\uC815 \uC2E0\uC6D0\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u3067\u306F\u30A2\u30AB\u30A6\u30F3\u30C8\u306E\u8B58\u5225\u306F\u5229\u7528\u3067\u304D\u307E\u305B\u3093\u3002", "\u8BE5\u8BBE\u5907\u4E0A\u65E0\u6CD5\u4F7F\u7528\u8D26\u6237\u8EAB\u4EFD\u3002", "La identidad de la cuenta no est\u00E1 disponible en este dispositivo.", "Nh\u1EADn d\u1EA1ng t\u00E0i kho\u1EA3n kh\u00F4ng kh\u1EA3 d\u1EE5ng tr\u00EAn thi\u1EBFt b\u1ECB n\u00E0y.", "Identitas akun tidak tersedia di perangkat ini.", "A identidade da conta n\u00E3o est\u00E1 dispon\u00EDvel neste dispositivo.", "هوية الحساب غير متاحة على هذا الجهاز."),
        "Activating add-on" to arrayOf("Ina-activate ang add-on", "\uC560\uB4DC\uC628 \uD65C\uC131\uD654 \uC911", "\u30A2\u30C9\u30AA\u30F3\u3092\u6709\u52B9\u5316\u3057\u3066\u3044\u307E\u3059", "\u6B63\u5728\u6FC0\u6D3B\u63D2\u4EF6", "Activando complemento", "K\u00EDch ho\u1EA1t ti\u1EC7n \u00EDch b\u1ED5 sung", "Mengaktifkan add-on", "Ativando complemento", "تفعيل الوظيفة الإضافية"),
        "Activating add-on safely" to arrayOf("Ina-activate nang ligtas ang add-on", "\uC560\uB4DC\uC628 \uC548\uC804\uD558\uAC8C \uD65C\uC131\uD654 \uC911", "\u30A2\u30C9\u30AA\u30F3\u3092\u5B89\u5168\u306B\u6709\u52B9\u5316\u3057\u3066\u3044\u307E\u3059", "\u6B63\u5728\u5B89\u5168\u6FC0\u6D3B\u63D2\u4EF6", "Activando complemento de manera segura", "K\u00EDch ho\u1EA1t ti\u1EC7n \u00EDch b\u1ED5 sung m\u1ED9t c\u00E1ch an to\u00E0n", "Mengaktifkan add-on dengan aman", "Ativando complemento com seguran\u00E7a", "تفعيل الوظيفة الإضافية بأمان"),
        "Active launcher access is required" to arrayOf("Kinakailangan ang active launcher access", "\uD65C\uC131 \uB7F0\uCC98 \uC811\uADFC\uC774 \uD544\uC694\uD569\uB2C8\uB2E4", "\u30A2\u30AF\u30C6\u30A3\u30D6\u306A\u30E9\u30F3\u30C1\u30E3\u30FC\u30A2\u30AF\u30BB\u30B9\u304C\u5FC5\u8981\u3067\u3059", "\u9700\u8981\u6D3B\u52A8\u7684\u542F\u52A8\u5668\u8BBF\u95EE\u6743\u9650", "Se requiere acceso activo al lanzador", "C\u1EA7n c\u00F3 quy\u1EC1n truy c\u1EADp tr\u00ECnh kh\u1EDFi ch\u1EA1y \u0111ang ho\u1EA1t \u0111\u1ED9ng", "Akses peluncur aktif diperlukan", "Acesso ativo ao launcher \u00E9 necess\u00E1rio", "مطلوب الوصول النشط للمشغل"),
        "Add-on architecture does not support the installed game" to arrayOf("Ang arkitektura ng add-on ay hindi sinusuportahan ang naka-install na laro", "\uC560\uB4DC\uC628 \uC544\uD0A4\uD14D\uCC98\uAC00 \uC124\uCE58\uB41C \uAC8C\uC784\uC744 \uC9C0\uC6D0\uD558\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4", "\u30A2\u30C9\u30AA\u30F3\u306E\u30A2\u30FC\u30AD\u30C6\u30AF\u30C1\u30E3\u306F\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u305F\u30B2\u30FC\u30E0\u3092\u30B5\u30DD\u30FC\u30C8\u3057\u3066\u3044\u307E\u305B\u3093", "\u63D2\u4EF6\u67B6\u6784\u4E0D\u652F\u6301\u5DF2\u5B89\u88C5\u7684\u6E38\u620F", "La arquitectura del complemento no es compatible con el juego instalado", "Ki\u1EBFn tr\u00FAc ti\u1EC7n \u00EDch b\u1ED5 sung kh\u00F4ng h\u1ED7 tr\u1EE3 tr\u00F2 ch\u01A1i \u0111\u00E3 c\u00E0i \u0111\u1EB7t", "Arsitektur add-on tidak mendukung game yang terpasang", "A arquitetura do complemento n\u00E3o \u00E9 compat\u00EDvel com o jogo instalado", "لا تدعم بنية الوظيفة الإضافية اللعبة المثبتة"),
        "Add-on architecture is not supported by this device" to arrayOf("Hindi suportado ng device na ito ang arkitektura ng add-on", "\uC560\uB4DC\uC628 \uC544\uD0A4\uD14D\uCC98\uAC00 \uC774 \uC7A5\uCE58\uC5D0\uC11C \uC9C0\uC6D0\uB418\uC9C0 \uC54A\uC2B5\uB2C8\uB2E4", "\u30A2\u30C9\u30AA\u30F3\u306E\u30A2\u30FC\u30AD\u30C6\u30AF\u30C1\u30E3\u306F\u3053\u306E\u30C7\u30D0\u30A4\u30B9\u3067\u306F\u30B5\u30DD\u30FC\u30C8\u3055\u308C\u3066\u3044\u307E\u305B\u3093", "\u8BE5\u8BBE\u5907\u4E0D\u652F\u6301\u63D2\u4EF6\u67B6\u6784", "La arquitectura del complemento no es compatible con este dispositivo", "Ki\u1EBFn tr\u00FAc ti\u1EC7n \u00EDch b\u1ED5 sung kh\u00F4ng \u0111\u01B0\u1EE3c thi\u1EBFt b\u1ECB n\u00E0y h\u1ED7 tr\u1EE3", "Arsitektur add-on tidak didukung oleh perangkat ini", "A arquitetura do complemento n\u00E3o \u00E9 suportada por este dispositivo", "لا يدعم هذا الجهاز بنية الوظائف الإضافية"),
        "Add-on download" to arrayOf("Pag-download ng add-on", "\uC560\uB4DC\uC628 \uB2E4\uC6B4\uB85C\uB4DC", "\u30A2\u30C9\u30AA\u30F3\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9", "\u63D2\u4EF6\u4E0B\u8F7D", "Descarga de complemento", "T\u1EA3i xu\u1ED1ng ti\u1EC7n \u00EDch b\u1ED5 sung", "Unduhan add-on", "Download do complemento", "تحميل الوظيفة الإضافية"),
        "Add-on download paused" to arrayOf("Pansamantalang hinto ang pag-download ng add-on", "\uC560\uB4DC\uC628 \uB2E4\uC6B4\uB85C\uB4DC \uC77C\uC2DC \uC911\uC9C0\uB428", "\u30A2\u30C9\u30AA\u30F3\u306E\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u304C\u4E00\u6642\u505C\u6B62\u3055\u308C\u307E\u3057\u305F", "\u63D2\u4EF6\u4E0B\u8F7D\u5DF2\u6682\u505C", "Descarga de complemento en pausa", "T\u1EA3i xu\u1ED1ng ti\u1EC7n \u00EDch b\u1ED5 sung \u0111\u00E3 t\u1EA1m d\u1EEBng", "Unduhan add-on dijeda", "Download do complemento pausado", "تم إيقاف تنزيل الوظيفة الإضافية مؤقتًا"),
        "Add-on isn't available" to arrayOf("Hindi available ang add-on", "\uC560\uB4DC\uC628\uC744 \uC0AC\uC6A9\uD560 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4", "\u30A2\u30C9\u30AA\u30F3\u306F\u5229\u7528\u3067\u304D\u307E\u305B\u3093", "\u63D2\u4EF6\u4E0D\u53EF\u7528", "El complemento no est\u00E1 disponible", "Ti\u1EC7n \u00EDch b\u1ED5 sung kh\u00F4ng kh\u1EA3 d\u1EE5ng", "Add-on tidak tersedia", "Complemento n\u00E3o est\u00E1 dispon\u00EDvel", "الوظيفة الإضافية غير متوفرة"),
        "Add-on repair" to arrayOf("Pag-aayos ng add-on", "\uC560\uB4DC\uC628 \uBCF5\uAD6C", "\u30A2\u30C9\u30AA\u30F3\u306E\u4FEE\u5FA9", "\u63D2\u4EF6\u4FEE\u590D", "Reparaci\u00F3n de complemento", "S\u1EEDa ch\u1EEFa ti\u1EC7n \u00EDch b\u1ED5 sung", "Perbaikan add-on", "Reparo do complemento", "إصلاح الوظيفة الإضافية"),
        "Add-on repaired" to arrayOf("Naayos ang add-on", "\uC560\uB4DC\uC628 \uBCF5\uAD6C \uC644\uB8CC", "\u30A2\u30C9\u30AA\u30F3\u304C\u4FEE\u5FA9\u3055\u308C\u307E\u3057\u305F", "\u63D2\u4EF6\u5DF2\u4FEE\u590D", "Complemento reparado", "Ti\u1EC7n \u00EDch b\u1ED5 sung \u0111\u00E3 \u0111\u01B0\u1EE3c s\u1EEDa ch\u1EEFa", "Add-on diperbaiki", "Complemento reparado", "تم إصلاح الوظيفة الإضافية"),
        "Add-on update" to arrayOf("Pag-update ng add-on", "\uC560\uB4DC\uC628 \uC5C5\uB370\uC774\uD2B8", "\u30A2\u30C9\u30AA\u30F3\u306E\u66F4\u65B0", "\u63D2\u4EF6\u66F4\u65B0", "Actualizaci\u00F3n de complemento", "C\u1EADp nh\u1EADt ti\u1EC7n \u00EDch b\u1ED5 sung", "Pembaruan add-on", "Atualiza\u00E7\u00E3o do complemento", "تحديث الوظيفة الإضافية"),
        "Add-on update activated successfully" to arrayOf("Matagumpay na na-activate ang update ng add-on", "\uC560\uB4DC\uC628 \uC5C5\uB370\uC774\uD2B8\uAC00 \uC131\uACF5\uC801\uC73C\uB85C \uD65C\uC131\uD654\uB418\uC5C8\uC2B5\uB2C8\uB2E4", "\u30A2\u30C9\u30AA\u30F3\u306E\u66F4\u65B0\u304C\u6B63\u5E38\u306B\u6709\u52B9\u5316\u3055\u308C\u307E\u3057\u305F", "\u63D2\u4EF6\u66F4\u65B0\u5DF2\u6210\u529F\u6FC0\u6D3B", "Actualizaci\u00F3n de complemento activada con \u00E9xito", "C\u1EADp nh\u1EADt ti\u1EC7n \u00EDch b\u1ED5 sung \u0111\u00E3 \u0111\u01B0\u1EE3c k\u00EDch ho\u1EA1t th\u00E0nh c\u00F4ng", "Pembaruan add-on berhasil diaktifkan", "Atualiza\u00E7\u00E3o do complemento ativada com sucesso", "تم تفعيل تحديث الوظيفة الإضافية بنجاح"),
        "Add-on updated" to arrayOf("Na-update ang add-on", "\uC560\uB4DC\uC628 \uC5C5\uB370\uC774\uD2B8\uB428", "\u30A2\u30C9\u30AA\u30F3\u304C\u66F4\u65B0\u3055\u308C\u307E\u3057\u305F", "\u63D2\u4EF6\u5DF2\u66F4\u65B0", "Complemento actualizado", "Ti\u1EC7n \u00EDch b\u1ED5 sung \u0111\u00E3 \u0111\u01B0\u1EE3c c\u1EADp nh\u1EADt", "Add-on diperbarui", "Complemento atualizado", "تم تحديث الوظيفة الإضافية"),
        "Added to the verified update queue" to arrayOf("Idinagdag sa naverify na update queue", "\uC778\uC99D\uB41C \uC5C5\uB370\uC774\uD2B8 \uB300\uAE30\uC5F4\uC5D0 \uCD94\uAC00\uB428", "\u691C\u8A3C\u6E08\u307F\u306E\u66F4\u65B0\u30AD\u30E5\u30FC\u306B\u8FFD\u52A0\u3055\u308C\u307E\u3057\u305F", "\u5DF2\u6DFB\u52A0\u5230\u5DF2\u9A8C\u8BC1\u7684\u66F4\u65B0\u961F\u5217", "Agregado a la cola de actualizaci\u00F3n verificada", "\u0110\u00E3 \u0111\u01B0\u1EE3c th\u00EAm v\u00E0o h\u00E0ng \u0111\u1EE3i c\u1EADp nh\u1EADt \u0111\u00E3 x\u00E1c minh", "Ditambahkan ke antrean pembaruan yang diverifikasi", "Adicionado \u00E0 fila de atualiza\u00E7\u00E3o verificada", "تمت إضافته إلى قائمة انتظار التحديث التي تم التحقق منها"),
        "After uninstalling, this add-on's Browse requirements will open. Download its companion game when offered, or choose Google Play." to arrayOf("Pagkatapos i-uninstall, magbubukas ang Browse requirements ng add-on na ito. I-download ang katambal nitong laro kapag inaalok, o piliin ang Google Play.", "\uC81C\uAC70 \uD6C4, \uC774 \uC560\uB4DC\uC628\uC758 \uD0D0\uC0C9 \uC694\uAD6C\uC0AC\uD56D\uC774 \uC5F4\uB9BD\uB2C8\uB2E4. \uC81C\uACF5\uB418\uBA74 \uB3D9\uBC18 \uAC8C\uC784\uC744 \uB2E4\uC6B4\uB85C\uB4DC\uD558\uAC70\uB098, Google Play\uB97C \uC120\uD0DD\uD558\uC138\uC694.", "\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u5F8C\u3001\u3053\u306E\u30A2\u30C9\u30AA\u30F3\u306E\u30D6\u30E9\u30A6\u30BA\u8981\u4EF6\u304C\u958B\u304D\u307E\u3059\u3002\u63D0\u4F9B\u3055\u308C\u305F\u5834\u5408\u306F\u305D\u306E\u95A2\u9023\u30B2\u30FC\u30E0\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u3059\u308B\u304B\u3001Google Play\u3092\u9078\u629E\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5378\u8F7D\u540E\uFF0C\u5C06\u6253\u5F00\u6B64\u9644\u52A0\u7EC4\u4EF6\u7684\u6D4F\u89C8\u8981\u6C42\u3002\u5728\u63D0\u4F9B\u65F6\u4E0B\u8F7D\u5176\u914D\u5957\u6E38\u620F\uFF0C\u6216\u9009\u62E9 Google Play\u3002", "Despu\u00E9s de desinstalar, se abrir\u00E1n los requisitos de Navegaci\u00F3n de este complemento. Descarga su juego complementario cuando se ofrezca, o elige Google Play.", "Sau khi g\u1EE1 c\u00E0i \u0111\u1EB7t, y\u00EAu c\u1EA7u Duy\u1EC7t c\u1EE7a ti\u1EC7n \u00EDch n\u00E0y s\u1EBD m\u1EDF ra. T\u1EA3i xu\u1ED1ng tr\u00F2 ch\u01A1i k\u00E8m theo khi \u0111\u01B0\u1EE3c \u0111\u1EC1 ngh\u1ECB, ho\u1EB7c ch\u1ECDn Google Play.", "Setelah mencopot pemasangan, persyaratan Browse untuk add-on ini akan terbuka. Unduh game pendampingnya saat ditawarkan, atau pilih Google Play.", "Depois de desinstalar, os requisitos de Navega\u00E7\u00E3o deste complemento ser\u00E3o abertos. Baixe seu jogo companion quando solicitado ou escolha Google Play.", "بعد إلغاء التثبيت، سيتم فتح متطلبات التصفح الخاصة بهذه الوظيفة الإضافية. قم بتنزيل اللعبة المصاحبة لها عند عرضها، أو اختر Google Play."),
        "All categories" to arrayOf("Lahat ng kategorya", "\uBAA8\uB4E0 \uCE74\uD14C\uACE0\uB9AC", "\u3059\u3079\u3066\u306E\u30AB\u30C6\u30B4\u30EA\u30FC", "\u6240\u6709\u7C7B\u522B", "Todas las categor\u00EDas", "T\u1EA5t c\u1EA3 danh m\u1EE5c", "Semua kategori", "Todas as categorias", "جميع الفئات"),
        "Allow Jester Mods to install app updates, then tap Install update again." to arrayOf("Pahintulutan ang Jester Mods na mag-install ng app updates, pagkatapos ay i-tap muli ang Install update.", "Jester Mods\uAC00 \uC571 \uC5C5\uB370\uC774\uD2B8\uB97C \uC124\uCE58\uD558\uB3C4\uB85D \uD5C8\uC6A9\uD55C \uB2E4\uC74C, \uB2E4\uC2DC \uC5C5\uB370\uC774\uD2B8 \uC124\uCE58\uB97C \uB204\uB974\uC138\uC694.", "Jester Mods \u304C\u30A2\u30D7\u30EA\u306E\u66F4\u65B0\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3067\u304D\u308B\u3088\u3046\u306B\u8A31\u53EF\u3057\u3066\u304B\u3089\u3001\u3082\u3046\u4E00\u5EA6\u300C\u66F4\u65B0\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u300D\u3092\u30BF\u30C3\u30D7\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5141\u8BB8 Jester Mods \u5B89\u88C5\u5E94\u7528\u66F4\u65B0\uFF0C\u7136\u540E\u518D\u6B21\u70B9\u51FB\u5B89\u88C5\u66F4\u65B0\u3002", "Permitir que Jester Mods instale actualizaciones de la aplicaci\u00F3n, luego toca Instalar actualizaci\u00F3n nuevamente.", "Cho ph\u00E9p Jester Mods c\u00E0i \u0111\u1EB7t c\u1EADp nh\u1EADt \u1EE9ng d\u1EE5ng, sau \u0111\u00F3 nh\u1EA5n C\u00E0i \u0111\u1EB7t c\u1EADp nh\u1EADt l\u1EA7n n\u1EEFa.", "Izinkan Jester Mods untuk menginstal pembaruan aplikasi, lalu ketuk Instal pembaruan lagi.", "Permita que o Jester Mods instale atualiza\u00E7\u00F5es de aplicativos, depois toque em Instalar atualiza\u00E7\u00E3o novamente.", "اسمح لـ Jester Mods بتثبيت تحديثات التطبيق، ثم اضغط على تثبيت التحديث مرة أخرى."),
        "Allow Jester Mods to install apps in Android settings, then try again." to arrayOf("Pahintulutan ang Jester Mods na mag-install ng apps sa Android settings, pagkatapos subukang muli.", "Android \uC124\uC815\uC5D0\uC11C Jester Mods\uAC00 \uC571\uC744 \uC124\uCE58\uD558\uB3C4\uB85D \uD5C8\uC6A9\uD55C \uB2E4\uC74C, \uB2E4\uC2DC \uC2DC\uB3C4\uD558\uC138\uC694.", "Android \u8A2D\u5B9A\u3067 Jester Mods \u304C\u30A2\u30D7\u30EA\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3067\u304D\u308B\u3088\u3046\u306B\u8A31\u53EF\u3057\u3066\u304B\u3089\u3001\u518D\u8A66\u884C\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5728 Android \u8BBE\u7F6E\u4E2D\u5141\u8BB8 Jester Mods \u5B89\u88C5\u5E94\u7528\uFF0C\u7136\u540E\u518D\u8BD5\u4E00\u6B21\u3002", "Permitir que Jester Mods instale aplicaciones en la configuraci\u00F3n de Android, luego vuelve a intentarlo.", "Cho ph\u00E9p Jester Mods c\u00E0i \u0111\u1EB7t \u1EE9ng d\u1EE5ng trong c\u00E0i \u0111\u1EB7t Android, sau \u0111\u00F3 th\u1EED l\u1EA1i.", "Izinkan Jester Mods untuk menginstal aplikasi di pengaturan Android, lalu coba lagi.", "Permita que o Jester Mods instale aplicativos nas configura\u00E7\u00F5es do Android, depois tente novamente.", "اسمح لـ Jester Mods بتثبيت التطبيقات في إعدادات Android، ثم حاول مرة أخرى."),
        "Allow Jester Mods to install apps, then tap Download game again." to arrayOf("Pahintulutan ang Jester Mods na mag-install ng apps, pagkatapos i-tap muli ang Download game.", "Jester Mods\uAC00 \uC571\uC744 \uC124\uCE58\uD558\uB3C4\uB85D \uD5C8\uC6A9\uD55C \uB2E4\uC74C, \uB2E4\uC2DC \uAC8C\uC784 \uB2E4\uC6B4\uB85C\uB4DC\uB97C \uB204\uB974\uC138\uC694.", "Jester Mods \u304C\u30A2\u30D7\u30EA\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3067\u304D\u308B\u3088\u3046\u306B\u8A31\u53EF\u3057\u3066\u304B\u3089\u3001\u518D\u5EA6\u300C\u30B2\u30FC\u30E0\u3092\u30C0\u30A6\u30F3\u30ED\u30FC\u30C9\u300D\u3092\u30BF\u30C3\u30D7\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5141\u8BB8 Jester Mods \u5B89\u88C5\u5E94\u7528\uFF0C\u7136\u540E\u518D\u6B21\u70B9\u51FB\u4E0B\u8F7D\u6E38\u620F\u3002", "Permitir que Jester Mods instale aplicaciones, luego toca Descargar juego nuevamente.", "Cho ph\u00E9p Jester Mods c\u00E0i \u0111\u1EB7t \u1EE9ng d\u1EE5ng, sau \u0111\u00F3 nh\u1EA5n T\u1EA3i tr\u00F2 ch\u01A1i l\u1EA7n n\u1EEFa.", "Izinkan Jester Mods untuk menginstal aplikasi, lalu ketuk Unduh game lagi.", "Permita que o Jester Mods instale aplicativos, depois toque em Baixar jogo novamente.", "اسمح لـ Jester Mods بتثبيت التطبيقات، ثم اضغط على تنزيل اللعبة مرة أخرى."),
        "Allow Jester Mods to install unknown apps before patching {0}." to arrayOf("Pahintulutan ang Jester Mods na mag-install ng unknown apps bago i-patch ang {0}.", "{0}\uB97C \uD328\uCE58\uD558\uAE30 \uC804\uC5D0 Jester Mods\uAC00 \uC54C \uC218 \uC5C6\uB294 \uC571\uC744 \uC124\uCE58\uD558\uB3C4\uB85D \uD5C8\uC6A9\uD558\uC138\uC694.", "{0} \u3092\u30D1\u30C3\u30C1\u3059\u308B\u524D\u306B\u3001Jester Mods \u304C\u4E0D\u660E\u306A\u30A2\u30D7\u30EA\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3067\u304D\u308B\u3088\u3046\u306B\u8A31\u53EF\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "\u5728\u4FEE\u8865 {0} \u524D\u5141\u8BB8 Jester Mods \u5B89\u88C5\u672A\u77E5\u5E94\u7528\u3002", "Permitir que Jester Mods instale aplicaciones desconocidas antes de parchear {0}.", "Cho ph\u00E9p Jester Mods c\u00E0i \u0111\u1EB7t c\u00E1c \u1EE9ng d\u1EE5ng kh\u00F4ng x\u00E1c \u0111\u1ECBnh tr\u01B0\u1EDBc khi v\u00E1 {0}.", "Izinkan Jester Mods untuk menginstal aplikasi yang tidak dikenal sebelum menambal {0}.", "Permita que o Jester Mods instale aplicativos desconhecidos antes de aplicar o patch em {0}.", "اسمح لـ Jester Mods بتثبيت تطبيقات غير معروفة قبل تصحيح {0}."),
        "Allow Jester Mods to install unknown apps, then return to review the {0} setup." to arrayOf("Pahintulutan ang Jester Mods na mag-install ng unknown apps, pagkatapos bumalik sa review ng {0} setup.", "Jester Mods\uAC00 \uC54C \uC218 \uC5C6\uB294 \uC571\uC744 \uC124\uCE58\uD558\uB3C4\uB85D \uD5C8\uC6A9\uD55C \uB2E4\uC74C, {0} \uC124\uC815 \uAC80\uD1A0\uB85C \uB3CC\uC544\uAC00\uC138\uC694.", "Jester Mods \u304C\u4E0D\u660E\u306A\u30A2\u30D7\u30EA\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3067\u304D\u308B\u3088\u3046\u306B\u8A31\u53EF\u3057\u3066\u304B\u3089\u3001{0} \u306E\u30BB\u30C3\u30C8\u30A2\u30C3\u30D7\u30EC\u30D3\u30E5\u30FC\u306B\u623B\u3063\u3066\u304F\u3060\u3055\u3044\u3002", "\u5141\u8BB8 Jester Mods \u5B89\u88C5\u672A\u77E5\u5E94\u7528\uFF0C\u7136\u540E\u8FD4\u56DE\u67E5\u770B {0} \u8BBE\u7F6E\u3002", "Permitir que Jester Mods instale aplicaciones desconocidas, luego regresa a revisar la configuraci\u00F3n de {0}.", "Cho ph\u00E9p Jester Mods c\u00E0i \u0111\u1EB7t c\u00E1c \u1EE9ng d\u1EE5ng kh\u00F4ng x\u00E1c \u0111\u1ECBnh, sau \u0111\u00F3 tr\u1EDF l\u1EA1i xem x\u00E9t thi\u1EBFt l\u1EADp {0}.", "Izinkan Jester Mods untuk menginstal aplikasi yang tidak dikenal, lalu kembali untuk meninjau pengaturan {0}.", "Permita que o Jester Mods instale aplicativos desconhecidos, depois volte para revisar a configura\u00E7\u00E3o de {0}.", "اسمح لـ Jester Mods بتثبيت تطبيقات غير معروفة، ثم ارجع لمراجعة إعداد {0}."),
        "Android closed without installing the update. Tap Install update to open it again." to arrayOf("Isinara ang Android nang hindi na-install ang update. I-tap ang Install update upang buksan itong muli.", "Android\uAC00 \uC5C5\uB370\uC774\uD2B8\uB97C \uC124\uCE58\uD558\uC9C0 \uC54A\uACE0 \uC885\uB8CC\uB418\uC5C8\uC2B5\uB2C8\uB2E4. \uB2E4\uC2DC \uC5F4\uB824\uBA74 \uC5C5\uB370\uC774\uD2B8 \uC124\uCE58\uB97C \uB204\uB974\uC138\uC694.", "Android \u304C\u66F4\u65B0\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u305B\u305A\u306B\u9589\u3058\u307E\u3057\u305F\u3002\u518D\u5EA6\u958B\u304F\u306B\u306F\u300C\u66F4\u65B0\u3092\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u300D\u3092\u30BF\u30C3\u30D7\u3057\u3066\u304F\u3060\u3055\u3044\u3002", "Android \u5728\u672A\u5B89\u88C5\u66F4\u65B0\u7684\u60C5\u51B5\u4E0B\u5173\u95ED\u3002\u70B9\u51FB\u5B89\u88C5\u66F4\u65B0\u4EE5\u518D\u6B21\u6253\u5F00\u3002", "Android se cerr\u00F3 sin instalar la actualizaci\u00F3n. Toca Instalar actualizaci\u00F3n para abrirla nuevamente.", "Android \u0111\u00E3 \u0111\u00F3ng m\u00E0 kh\u00F4ng c\u00E0i \u0111\u1EB7t b\u1EA3n c\u1EADp nh\u1EADt. Nh\u1EA5n C\u00E0i \u0111\u1EB7t c\u1EADp nh\u1EADt \u0111\u1EC3 m\u1EDF l\u1EA1i.", "Android ditutup tanpa menginstal pembaruan. Ketuk Instal pembaruan untuk membukanya lagi.", "Android foi fechado sem instalar a atualiza\u00E7\u00E3o. Toque em Instalar atualiza\u00E7\u00E3o para abri-la novamente.", "تم إغلاق Android دون تثبيت التحديث. انقر فوق تثبيت التحديث لفتحه مرة أخرى."),
        "Android confirmed the uninstall, but the game still appears installed. Nothing else was changed." to arrayOf("Kinumpirma ng Android ang pag-uninstall, ngunit ang laro ay mukhang naka-install pa rin. Wala nang iba pang nabago.", "Android\uAC00 \uC0AD\uC81C\uB97C \uD655\uC778\uD588\uC9C0\uB9CC, \uAC8C\uC784\uC774 \uC5EC\uC804\uD788 \uC124\uCE58\uB41C \uAC83\uC73C\uB85C \uB098\uD0C0\uB0A9\uB2C8\uB2E4. \uB2E4\uB978 \uAC83\uC740 \uBCC0\uACBD\uB418\uC9C0 \uC54A\uC558\uC2B5\uB2C8\uB2E4.", "Android\u306F\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u307E\u3057\u305F\u304C\u3001\u30B2\u30FC\u30E0\u306F\u307E\u3060\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u3066\u3044\u308B\u3088\u3046\u306B\u898B\u3048\u307E\u3059\u3002\u4ED6\u306B\u306F\u4F55\u3082\u5909\u66F4\u3055\u308C\u3066\u3044\u307E\u305B\u3093\u3002", "Android \u5DF2\u786E\u8BA4\u5378\u8F7D\uFF0C\u4F46\u6E38\u620F\u4ECD\u663E\u793A\u5DF2\u5B89\u88C5\u3002\u5176\u4ED6\u672A\u4F5C\u66F4\u6539\u3002", "Android confirm\u00F3 la desinstalaci\u00F3n, pero el juego a\u00FAn aparece instalado. No se cambi\u00F3 nada m\u00E1s.", "Android \u0111\u00E3 x\u00E1c nh\u1EADn g\u1EE1 c\u00E0i \u0111\u1EB7t, nh\u01B0ng tr\u00F2 ch\u01A1i v\u1EABn xu\u1EA5t hi\u1EC7n l\u00E0 \u0111\u00E3 c\u00E0i \u0111\u1EB7t. Kh\u00F4ng c\u00F3 g\u00EC kh\u00E1c thay \u0111\u1ED5i.", "Android mengonfirmasi pencopotan, tetapi game masih terlihat terpasang. Tidak ada yang lain yang diubah.", "O Android confirmou a desinstala\u00E7\u00E3o, mas o jogo ainda aparece instalado. Nada mais foi alterado.", "أكد Android عملية إلغاء التثبيت، ولكن لا تزال اللعبة تبدو مثبتة. ولم يتغير شيء آخر."),
        "Android confirmed the uninstall, but the previous patch still appears installed." to arrayOf("Kinumpirma ng Android ang pag-uninstall, ngunit ang naunang patch ay mukhang naka-install pa rin.", "Android\uAC00 \uC0AD\uC81C\uB97C \uD655\uC778\uD588\uC9C0\uB9CC, \uC774\uC804 \uD328\uCE58\uAC00 \uC5EC\uC804\uD788 \uC124\uCE58\uB41C \uAC83\uC73C\uB85C \uB098\uD0C0\uB0A9\uB2C8\uB2E4.", "Android\u306F\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u307E\u3057\u305F\u304C\u3001\u4EE5\u524D\u306E\u30D1\u30C3\u30C1\u306F\u307E\u3060\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u3066\u3044\u308B\u3088\u3046\u306B\u898B\u3048\u307E\u3059\u3002", "Android \u5DF2\u786E\u8BA4\u5378\u8F7D\uFF0C\u4F46\u4E4B\u524D\u7684\u8865\u4E01\u4ECD\u663E\u793A\u5DF2\u5B89\u88C5\u3002", "Android confirm\u00F3 la desinstalaci\u00F3n, pero el parche anterior a\u00FAn aparece instalado.", "Android \u0111\u00E3 x\u00E1c nh\u1EADn g\u1EE1 c\u00E0i \u0111\u1EB7t, nh\u01B0ng b\u1EA3n v\u00E1 tr\u01B0\u1EDBc \u0111\u00F3 v\u1EABn xu\u1EA5t hi\u1EC7n l\u00E0 \u0111\u00E3 c\u00E0i \u0111\u1EB7t.", "Android mengonfirmasi pencopotan, tetapi patch sebelumnya masih terlihat terpasang.", "O Android confirmou a desinstala\u00E7\u00E3o, mas o patch anterior ainda aparece instalado.", "أكد Android عملية الإزالة، ولكن التصحيح السابق لا يزال يظهر مثبتًا."),
        "Android confirmed the uninstall, but the {0} shell still appears installed." to arrayOf("Kinumpirma ng Android ang pag-uninstall, ngunit ang {0} shell ay mukhang naka-install pa rin.", "Android\uAC00 \uC0AD\uC81C\uB97C \uD655\uC778\uD588\uC9C0\uB9CC, {0} \uC140\uC774 \uC5EC\uC804\uD788 \uC124\uCE58\uB41C \uAC83\uC73C\uB85C \uB098\uD0C0\uB0A9\uB2C8\uB2E4.", "Android\u306F\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u307E\u3057\u305F\u304C\u3001{0} \u30B7\u30A7\u30EB\u306F\u307E\u3060\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3055\u308C\u3066\u3044\u308B\u3088\u3046\u306B\u898B\u3048\u307E\u3059\u3002", "Android \u5DF2\u786E\u8BA4\u5378\u8F7D\uFF0C\u4F46 {0} \u5916\u58F3\u4ECD\u663E\u793A\u5DF2\u5B89\u88C5\u3002", "Android confirm\u00F3 la desinstalaci\u00F3n, pero la shell {0} a\u00FAn aparece instalada.", "Android \u0111\u00E3 x\u00E1c nh\u1EADn g\u1EE1 c\u00E0i \u0111\u1EB7t, nh\u01B0ng giao di\u1EC7n {0} v\u1EABn xu\u1EA5t hi\u1EC7n l\u00E0 \u0111\u00E3 c\u00E0i \u0111\u1EB7t.", "Android mengonfirmasi pencopotan, tetapi shell {0} masih terlihat terpasang.", "O Android confirmou a desinstala\u00E7\u00E3o, mas o shell {0} ainda aparece instalado.", "أكد Android عملية الإزالة، ولكن لا يزال يظهر {0} Shell مثبتًا."),
        "Android confirmed the uninstall. Checking that the previous patch is fully removed." to arrayOf("Kinumpirma ng Android ang pag-uninstall. Tinitingnan kung ang naunang patch ay lubos nang naalis.", "Android\uAC00 \uC0AD\uC81C\uB97C \uD655\uC778\uD588\uC2B5\uB2C8\uB2E4. \uC774\uC804 \uD328\uCE58\uAC00 \uC644\uC804\uD788 \uC81C\uAC70\uB418\uC5C8\uB294\uC9C0 \uD655\uC778 \uC911\uC785\uB2C8\uB2E4.", "Android\u306F\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u307E\u3057\u305F\u3002\u4EE5\u524D\u306E\u30D1\u30C3\u30C1\u304C\u5B8C\u5168\u306B\u524A\u9664\u3055\u308C\u3066\u3044\u308B\u304B\u78BA\u8A8D\u3057\u3066\u3044\u307E\u3059\u3002", "Android \u5DF2\u786E\u8BA4\u5378\u8F7D\u3002\u6B63\u5728\u68C0\u67E5\u4E4B\u524D\u7684\u8865\u4E01\u662F\u5426\u5DF2\u5B8C\u5168\u79FB\u9664\u3002", "Android confirm\u00F3 la desinstalaci\u00F3n. Verificando que el parche anterior est\u00E9 completamente eliminado.", "Android \u0111\u00E3 x\u00E1c nh\u1EADn g\u1EE1 c\u00E0i \u0111\u1EB7t. Ki\u1EC3m tra xem b\u1EA3n v\u00E1 tr\u01B0\u1EDBc \u0111\u00F3 \u0111\u00E3 \u0111\u01B0\u1EE3c g\u1EE1 ho\u00E0n to\u00E0n.", "Android mengonfirmasi pencopotan. Memeriksa bahwa patch sebelumnya telah sepenuhnya dihapus.", "O Android confirmou a desinstala\u00E7\u00E3o. Verificando se o patch anterior foi totalmente removido.", "أكد Android إلغاء التثبيت. التحقق من إزالة التصحيح السابق بالكامل."),
        "Android confirmed the uninstall. Waiting for its package records to finish updating." to arrayOf("Kinumpirma ng Android ang pag-uninstall. Naghihintay na matapos ang pag-update ng mga rekord ng package nito.", "Android\uAC00 \uC0AD\uC81C\uB97C \uD655\uC778\uD588\uC2B5\uB2C8\uB2E4. \uD328\uD0A4\uC9C0 \uAE30\uB85D\uC774 \uC5C5\uB370\uC774\uD2B8\uB418\uB294 \uAC83\uC744 \uAE30\uB2E4\uB9AC\uB294 \uC911\uC785\uB2C8\uB2E4.", "Android\u306F\u30A2\u30F3\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u3092\u78BA\u8A8D\u3057\u307E\u3057\u305F\u3002\u30D1\u30C3\u30B1\u30FC\u30B8\u8A18\u9332\u306E\u66F4\u65B0\u304C\u5B8C\u4E86\u3059\u308B\u306E\u3092\u5F85\u3063\u3066\u3044\u307E\u3059\u3002", "Android \u5DF2\u786E\u8BA4\u5378\u8F7D\u3002\u6B63\u5728\u7B49\u5F85\u5176\u8F6F\u4EF6\u5305\u8BB0\u5F55\u5B8C\u6210\u66F4\u65B0\u3002", "Android confirm\u00F3 la desinstalaci\u00F3n. Esperando a que sus registros de paquetes terminen de actualizarse.", "Android \u0111\u00E3 x\u00E1c nh\u1EADn g\u1EE1 c\u00E0i \u0111\u1EB7t. \u0110ang ch\u1EDD h\u1ED3 s\u01A1 g\u00F3i c\u1EE7a n\u00F3 c\u1EADp nh\u1EADt xong.", "Android mengonfirmasi pencopotan. Menunggu catatan paketnya selesai diperbarui.", "O Android confirmou a desinstala\u00E7\u00E3o. Aguardando a atualiza\u00E7\u00E3o dos registros do pacote.", "أكد Android إلغاء التثبيت. في انتظار انتهاء تحديث سجلات الحزمة الخاصة به."),
        "Android could not open the unknown-app installation setting." to arrayOf("Hindi mabuksan ng Android ang setting ng pag-install ng unknown-app.", "Android\uAC00 \uC54C \uC218 \uC5C6\uB294 \uC571 \uC124\uCE58 \uC124\uC815\uC744 \uC5F4 \uC218 \uC5C6\uC2B5\uB2C8\uB2E4.", "Android\u306F\u4E0D\u660E\u306A\u30A2\u30D7\u30EA\u306E\u30A4\u30F3\u30B9\u30C8\u30FC\u30EB\u8A2D\u5B9A\u3092\u958B\u304F\u3053\u3068\u304C\u3067\u304D\u307E\u305B\u3093\u3067\u3057\u305F\u3002", "Android \u65E0\u6CD5\u6253\u5F00\u672A\u77E5\u5E94\u7528\u7684\u5B89\u88C5\u8BBE\u7F6E\u3002", "Android no pudo abrir la configuraci\u00F3n de instalaci\u00F3n de aplicaciones desconocidas.", "Android kh\u00F4ng th\u1EC3 m\u1EDF c\u00E0i \u0111\u1EB7t c\u00E0i \u0111\u1EB7t \u1EE9ng d\u1EE5ng kh\u00F4ng x\u00E1c \u0111\u1ECBnh.", "Android tidak dapat membuka pengaturan pemasangan aplikasi tidak dikenal.", "O Android n\u00E3o conseguiu abrir a configura\u00E7\u00E3o de instala\u00E7\u00E3o de aplicativo desconhecido.", "تعذر على Android فتح إعداد تثبيت التطبيق غير المعروف."),
